@Import(TestcontainersConfiguration.class)
class SondaAtualizacaoIT {

	@Autowired
	private MockMvc mockMvc;

	@Autowired
	private JsonMapper jsonMapper;

	@Test
	void sondar() throws Exception {
		Conta conta = new ClienteApiDeTeste(mockMvc, jsonMapper).cadastrar("sonda");
		List<String> corpos = List.of("{\"user\":null}", "{}", "{\"user\":{\"email\":\"\"}}",
				"{\"user\":{\"username\":\"\"}}", "{\"user\":{\"password\":\"\"}}", "{\"user\":{\"email\":\"   \"}}",
				"{\"user\":{\"email\":\"notanemail\"}}", "{\"user\":{\"email\":\"a@b\"}}",
				"{\"user\":{\"email\":\"invalid-email\"}}", "{\"user\":{\"username\":null}}",
				"{\"user\":{\"foo\":\"bar\"}}", "{\"user\":[]}", "{\"user\":{\"email\":123}}",
